import{_ as a,o,c as e,a2 as l}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Contenido Programático: Proyecto Sociotecnológico (Trayecto 1)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/Contenido_Programatico.md","filePath":"materias/Proyecto_Sociotecnologico_I/Contenido_Programatico.md"}'),c={name:"materias/Proyecto_Sociotecnologico_I/Contenido_Programatico.md"};function n(r,i,d,t,s,u){return o(),e("div",null,[...i[0]||(i[0]=[l('<h1 id="contenido-programatico-proyecto-sociotecnologico-trayecto-1" tabindex="-1">Contenido Programático: Proyecto Sociotecnológico (Trayecto 1) <a class="header-anchor" href="#contenido-programatico-proyecto-sociotecnologico-trayecto-1" aria-label="Permalink to &quot;Contenido Programático: Proyecto Sociotecnológico (Trayecto 1)&quot;">​</a></h1><p><strong>Unidad Curricular:</strong> Proyecto Sociotecnológico <strong>Unidades Crédito:</strong> 9 <strong>Duración:</strong> 3 trimestres <strong>Código:</strong> PTP139</p><hr><h2 id="🔌-saberes" tabindex="-1">🔌 SABERES <a class="header-anchor" href="#🔌-saberes" aria-label="Permalink to &quot;🔌 SABERES&quot;">​</a></h2><h3 id="unidad-1-la-comunidad-como-resultado-de-la-universidad" tabindex="-1">Unidad 1: La comunidad como resultado de la universidad <a class="header-anchor" href="#unidad-1-la-comunidad-como-resultado-de-la-universidad" aria-label="Permalink to &quot;Unidad 1: La comunidad como resultado de la universidad&quot;">​</a></h3><ul><li>Definición de Sociedad</li><li>Definición de Comunidad</li><li>Esquema del informe del proyecto y portafolio (físico y digital)</li><li>Abordaje de la comunidad:</li><li>Definición de Diagnóstico Participativo</li><li>Diagnóstico participativo como herramienta para la identificación de problemas</li><li>Levantamiento de Información (técnicas e instrumentos de recolección de datos)</li><li>Elementos del diagnóstico</li><li>Finalidad del diagnóstico</li><li>Normas del diagnóstico</li><li>Análisis de involucrados</li><li>Visitas a la comunidad</li><li>Organización de la información</li><li>Análisis y Socialización de resultados del diagnóstico participativo en y con la comunidad</li></ul><h3 id="unidad-2-principios-del-enfoque-del-marco-logico-eml" tabindex="-1">Unidad 2: Principios del Enfoque del Marco Lógico (EML) <a class="header-anchor" href="#unidad-2-principios-del-enfoque-del-marco-logico-eml" aria-label="Permalink to &quot;Unidad 2: Principios del Enfoque del Marco Lógico (EML)&quot;">​</a></h3><ul><li>Definición de Marco Lógico</li><li>Ciclo del Proyecto bajo el EML</li><li>Fases de la Metodología:</li></ul><h3 id="unidad-3-definicion-e-identificacion-del-problema" tabindex="-1">Unidad 3: Definición e identificación del problema <a class="header-anchor" href="#unidad-3-definicion-e-identificacion-del-problema" aria-label="Permalink to &quot;Unidad 3: Definición e identificación del problema&quot;">​</a></h3><ul><li>Análisis de problemas</li><li>Determinación de las causas del problema</li><li>Priorizar las causas del problema</li><li>Determinar los efectos y las causas</li><li>Realización del Árbol de problemas (causa-efecto)</li><li>Validación del problema con la comunidad</li></ul><h3 id="unidad-4-formulacion-del-proyecto" tabindex="-1">Unidad 4: Formulación del Proyecto <a class="header-anchor" href="#unidad-4-formulacion-del-proyecto" aria-label="Permalink to &quot;Unidad 4: Formulación del Proyecto&quot;">​</a></h3><ul><li>Análisis de objetivos</li><li>Determinación de fines</li><li>Determinación de medios</li><li>Priorización de fines y medios</li><li>Realización del Árbol de objetivos (fines-medios)</li><li>Análisis de alternativas</li><li>Validación de objetivos con la comunidad</li><li>Estructura Analítica del Proyecto (EAP)</li></ul><h3 id="unidad-5-planificacion-del-proyecto-sociotecnologico" tabindex="-1">Unidad 5: Planificación del Proyecto Sociotecnológico <a class="header-anchor" href="#unidad-5-planificacion-del-proyecto-sociotecnologico" aria-label="Permalink to &quot;Unidad 5: Planificación del Proyecto Sociotecnológico&quot;">​</a></h3><ul><li>Identificar actividades y tareas a desarrollar en el proyecto de Soporte Técnico a Equipos y Soporte a Usuarios.</li><li>Determinación de los recursos necesarios: técnicos, materiales, humanos</li><li>Fundamentación Legal</li><li>Presupuesto: descripción de los costos del proyecto</li><li>Cronograma de actividades (Diagrama de Gantt)</li></ul><h3 id="unidad-6-ejecucion-del-proyecto-sociotecnologico" tabindex="-1">Unidad 6: Ejecución del Proyecto Sociotecnológico <a class="header-anchor" href="#unidad-6-ejecucion-del-proyecto-sociotecnologico" aria-label="Permalink to &quot;Unidad 6: Ejecución del Proyecto Sociotecnológico&quot;">​</a></h3><ul><li>Ejecución de las actividades de Soporte Técnico a Usuarios y Equipos en y con la comunidad</li></ul><h3 id="unidad-7-evaluacion-del-proyecto-sociotecnologico" tabindex="-1">Unidad 7: Evaluación del Proyecto Sociotecnológico <a class="header-anchor" href="#unidad-7-evaluacion-del-proyecto-sociotecnologico" aria-label="Permalink to &quot;Unidad 7: Evaluación del Proyecto Sociotecnológico&quot;">​</a></h3><ul><li>Evaluación de resultados por parte del docente y la comunidad</li><li>Entrega de informe final y presentación de portafolio</li></ul><hr><h2 id="🛠️-estrategias" tabindex="-1">🛠️ ESTRATEGIAS <a class="header-anchor" href="#🛠️-estrategias" aria-label="Permalink to &quot;🛠️ ESTRATEGIAS&quot;">​</a></h2><ul><li>Los actores deben abordar la comunidad para conocerla, describirla y detectar necesidades.</li><li>Emplear metodología del marco lógico para el abordaje comunitario.</li><li>Realizar talleres, conversatorios o charlas con invitados especiales de organismos que apoyen la ejecución de proyectos.</li><li>Se sugiere taller de comunicación asertiva.</li><li>Investigar sobre los proyectos informáticos locales, regionales y nacionales y los organismos que apoyan la ejecución de los mismos.</li><li>Plantear alternativas de soluciones ante situaciones y problemas reales, relacionados con soporte técnico a usuarios y equipos.</li><li>Los actores deben ejecutar en la comunidad seleccionada el proyecto planteado.</li><li>Los actores deben realizar las actividades planificadas para el soporte técnico y de usuarios.</li><li>Los docentes deben supervisar en el campo la ejecución del proyecto.</li><li>Elaboración y presentación ante la comunidad (Universitaria y beneficiaria) del proyecto final.</li></ul><h2 id="📦-recursos" tabindex="-1">📦 RECURSOS <a class="header-anchor" href="#📦-recursos" aria-label="Permalink to &quot;📦 RECURSOS&quot;">​</a></h2><ul><li>Pizarra magnética.</li><li>Marcadores.</li><li>Material Educativo Computarizado: Material Instructivo, Software.</li><li>Computador.</li><li>Proyector Multimedia.</li><li>Plataforma Tecnológica.</li><li>Aula de encuentros, aula taller, laboratorios.</li></ul><h2 id="📈-evaluacion" tabindex="-1">📈 EVALUACIÓN <a class="header-anchor" href="#📈-evaluacion" aria-label="Permalink to &quot;📈 EVALUACIÓN&quot;">​</a></h2><ul><li>Formativa.</li><li>Sumativa.</li><li>Entrega y presentación del Informe: indicándose las actividades y fases desarrolladas.</li><li>Coevaluación.</li><li>Autoevaluación.</li></ul>',25)])])}const g=a(c,[["render",n]]);export{p as __pageData,g as default};
